\begin{linenumbers}
Let $\mathbf 0_c$ be the null code of rank $0$ with $\operatorname{El}(\mathbf 0_c)=\varnothing$.
Because $0<\kappa_i$, we have $\mathbf 0_c\in\mathcal U_i$,
hence $\varnothing\in\mathbf{Set}_{\mathcal U_i}$.
\end{linenumbers}

\label{lem:sum}
For every pair of objects $A,B\in\mathbf{Set}_{\mathcal U_i}$ the coproduct
$A\sqcup B$ is again an element of\/ $\mathbf{Set}_{\mathcal U_i}$.

\label{lem:coeq}
For every parallel pair $f,g\colon R\to S$ in $\mathbf{Set}_{\mathcal U_i}$
the coequaliser $\operatorname{Coeq}(f,g)$ lies in $\mathbf{Set}_{\mathcal U_i}$.

\label{lem:maclane}
In any category, the initial object, binary coproducts, and coequalisers
generate all finite colimits.

\begin{linenumbers}
See Mac Lane, \emph{Categories for the Working Mathematician},
dual of Thm.~V.2.3.
\end{linenumbers}
